import matplotlib.pyplot as plt

def plot_tuples(tuples):
    k_values = []
    k_2s_values = []

    for n, k, s in tuples:
        k_values.append(k)
        k_2s_values.append(k + 2 * s)

    plt.figure(figsize=(8, 5))
    plt.scatter(k_values, k_2s_values, color='b', label='$k + 2s$ vs. $k$')
    plt.xlabel('$k$')
    plt.ylabel('$k + 2s$')
    plt.title('Plot of $k + 2s$ vs. $k$')
    plt.legend()
    plt.grid()
    plt.show()

